-- The demo deck gets slides (ticket #184; GLOSSARY: Deck, Slide, Demo Mode). "Board update" was an empty deck, so
-- exporting it gave one title slide. It now has five: a title slide and four slides of the demo's own Metrics
-- (Revenue against Cost, Margin, Orders and Average order value, Support tickets and Return rate), as line widgets.
-- The document is a tldraw snapshot, made in the deck editor and kept as text here. Metric ids are looked up by slug
-- in the demo Workspace when the demo is reset, because real Workspaces share the same id sequence; the title
-- slide names the current month, like the deck's name.
create or replace function public.prototype_reset_decks()
 returns void
 language plpgsql
 security definer
 set search_path to 'public'
as $function$
declare
  doc text := $deck${"schema":{"schemaVersion":2,"sequences":{"com.tldraw.asset":1,"com.tldraw.asset.bookmark":2,"com.tldraw.asset.image":6,"com.tldraw.asset.video":5,"com.tldraw.binding.arrow":1,"com.tldraw.camera":1,"com.tldraw.document":2,"com.tldraw.instance":26,"com.tldraw.instance_page_state":5,"com.tldraw.instance_presence":6,"com.tldraw.page":1,"com.tldraw.pointer":1,"com.tldraw.shape":4,"com.tldraw.shape.arrow":8,"com.tldraw.shape.bookmark":2,"com.tldraw.shape.draw":5,"com.tldraw.shape.embed":4,"com.tldraw.shape.frame":1,"com.tldraw.shape.geo":12,"com.tldraw.shape.group":0,"com.tldraw.shape.highlight":4,"com.tldraw.shape.image":5,"com.tldraw.shape.line":5,"com.tldraw.shape.note":13,"com.tldraw.shape.text":4,"com.tldraw.shape.video":4,"com.tldraw.shape.ziffr-widget":0,"com.tldraw.store":5,"com.tldraw.user":1}},"store":{"document:document":{"gridSize":10,"id":"document:document","meta":{},"name":"","typeName":"document"},"page:page":{"id":"page:page","index":"a1","meta":{},"name":"Page 1","typeName":"page"},"shape:demo-board-s1":{"id":"shape:demo-board-s1","index":"a1","isLocked":false,"meta":{},"opacity":1,"parentId":"page:page","props":{"color":"black","h":720,"name":"Slide 1","w":1280},"rotation":0,"type":"frame","typeName":"shape","x":0,"y":0},"shape:demo-board-s1-sub":{"id":"shape:demo-board-s1-sub","index":"a2","isLocked":false,"meta":{},"opacity":1,"parentId":"shape:demo-board-s1","props":{"autoSize":false,"color":"black","font":"sans","richText":{"content":[{"content":[{"text":"Northwind Goods, __MONTH__","type":"text"}],"type":"paragraph"}],"type":"doc"},"scale":1,"size":"m","textAlign":"start","w":1152},"rotation":0,"type":"text","typeName":"shape","x":64,"y":380},"shape:demo-board-s1-title":{"id":"shape:demo-board-s1-title","index":"a1","isLocked":false,"meta":{},"opacity":1,"parentId":"shape:demo-board-s1","props":{"autoSize":false,"color":"black","font":"sans","richText":{"content":[{"content":[{"text":"Board update","type":"text"}],"type":"paragraph"}],"type":"doc"},"scale":1.7818181818181817,"size":"xl","textAlign":"start","w":1152},"rotation":0,"type":"text","typeName":"shape","x":64,"y":250},"shape:demo-board-s2":{"id":"shape:demo-board-s2","index":"a2","isLocked":false,"meta":{},"opacity":1,"parentId":"page:page","props":{"color":"black","h":720,"name":"Slide 2","w":1280},"rotation":0,"type":"frame","typeName":"shape","x":0,"y":840},"shape:demo-board-s2-cost":{"id":"shape:demo-board-s2-cost","index":"a3","isLocked":false,"meta":{},"opacity":1,"parentId":"shape:demo-board-s2","props":{"h":320,"metricIds":["__M_cost__"],"settings":"{\"window\":12,\"showTarget\":true,\"showForecast\":false}","template":"line","title":"","w":560},"rotation":0,"type":"ziffr-widget","typeName":"shape","x":656,"y":166},"shape:demo-board-s2-revenue":{"id":"shape:demo-board-s2-revenue","index":"a2","isLocked":false,"meta":{},"opacity":1,"parentId":"shape:demo-board-s2","props":{"h":320,"metricIds":["__M_revenue__"],"settings":"{\"window\":12,\"showTarget\":true,\"showForecast\":false}","template":"line","title":"","w":560},"rotation":0,"type":"ziffr-widget","typeName":"shape","x":64,"y":166},"shape:demo-board-s2-title":{"id":"shape:demo-board-s2-title","index":"a1","isLocked":false,"meta":{},"opacity":1,"parentId":"shape:demo-board-s2","props":{"autoSize":false,"color":"black","font":"sans","richText":{"content":[{"content":[{"text":"Revenue against cost","type":"text"}],"type":"paragraph"}],"type":"doc"},"scale":1.2727272727272727,"size":"xl","textAlign":"start","w":952},"rotation":0,"type":"text","typeName":"shape","x":64,"y":56},"shape:demo-board-s3":{"id":"shape:demo-board-s3","index":"a3","isLocked":false,"meta":{},"opacity":1,"parentId":"page:page","props":{"color":"black","h":720,"name":"Slide 3","w":1280},"rotation":0,"type":"frame","typeName":"shape","x":0,"y":1680},"shape:demo-board-s3-margin":{"id":"shape:demo-board-s3-margin","index":"a2","isLocked":false,"meta":{},"opacity":1,"parentId":"shape:demo-board-s3","props":{"h":480,"metricIds":["__M_margin__"],"settings":"{\"window\":12,\"showTarget\":true,\"showForecast\":false}","template":"line","title":"","w":1152},"rotation":0,"type":"ziffr-widget","typeName":"shape","x":64,"y":166},"shape:demo-board-s3-title":{"id":"shape:demo-board-s3-title","index":"a1","isLocked":false,"meta":{},"opacity":1,"parentId":"shape:demo-board-s3","props":{"autoSize":false,"color":"black","font":"sans","richText":{"content":[{"content":[{"text":"Margin, month by month","type":"text"}],"type":"paragraph"}],"type":"doc"},"scale":1.2727272727272727,"size":"xl","textAlign":"start","w":952},"rotation":0,"type":"text","typeName":"shape","x":64,"y":56},"shape:demo-board-s4":{"id":"shape:demo-board-s4","index":"a4","isLocked":false,"meta":{},"opacity":1,"parentId":"page:page","props":{"color":"black","h":720,"name":"Slide 4","w":1280},"rotation":0,"type":"frame","typeName":"shape","x":0,"y":2520},"shape:demo-board-s4-aov":{"id":"shape:demo-board-s4-aov","index":"a3","isLocked":false,"meta":{},"opacity":1,"parentId":"shape:demo-board-s4","props":{"h":320,"metricIds":["__M_average-order-value__"],"settings":"{\"window\":12,\"showTarget\":true,\"showForecast\":false}","template":"line","title":"","w":560},"rotation":0,"type":"ziffr-widget","typeName":"shape","x":656,"y":166},"shape:demo-board-s4-orders":{"id":"shape:demo-board-s4-orders","index":"a2","isLocked":false,"meta":{},"opacity":1,"parentId":"shape:demo-board-s4","props":{"h":320,"metricIds":["__M_orders__"],"settings":"{\"window\":12,\"showTarget\":true,\"showForecast\":false}","template":"line","title":"","w":560},"rotation":0,"type":"ziffr-widget","typeName":"shape","x":64,"y":166},"shape:demo-board-s4-title":{"id":"shape:demo-board-s4-title","index":"a1","isLocked":false,"meta":{},"opacity":1,"parentId":"shape:demo-board-s4","props":{"autoSize":false,"color":"black","font":"sans","richText":{"content":[{"content":[{"text":"Orders and what they are worth","type":"text"}],"type":"paragraph"}],"type":"doc"},"scale":1.2727272727272727,"size":"xl","textAlign":"start","w":952},"rotation":0,"type":"text","typeName":"shape","x":64,"y":56},"shape:demo-board-s5":{"id":"shape:demo-board-s5","index":"a5","isLocked":false,"meta":{},"opacity":1,"parentId":"page:page","props":{"color":"black","h":720,"name":"Slide 5","w":1280},"rotation":0,"type":"frame","typeName":"shape","x":0,"y":3360},"shape:demo-board-s5-returns":{"id":"shape:demo-board-s5-returns","index":"a3","isLocked":false,"meta":{},"opacity":1,"parentId":"shape:demo-board-s5","props":{"h":320,"metricIds":["__M_return-rate__"],"settings":"{\"window\":12,\"showTarget\":true,\"showForecast\":false}","template":"line","title":"","w":560},"rotation":0,"type":"ziffr-widget","typeName":"shape","x":656,"y":166},"shape:demo-board-s5-tickets":{"id":"shape:demo-board-s5-tickets","index":"a2","isLocked":false,"meta":{},"opacity":1,"parentId":"shape:demo-board-s5","props":{"h":320,"metricIds":["__M_support-tickets__"],"settings":"{\"window\":12,\"showTarget\":true,\"showForecast\":false}","template":"line","title":"","w":560},"rotation":0,"type":"ziffr-widget","typeName":"shape","x":64,"y":166},"shape:demo-board-s5-title":{"id":"shape:demo-board-s5-title","index":"a1","isLocked":false,"meta":{},"opacity":1,"parentId":"shape:demo-board-s5","props":{"autoSize":false,"color":"black","font":"sans","richText":{"content":[{"content":[{"text":"Customers: support and returns","type":"text"}],"type":"paragraph"}],"type":"doc"},"scale":1.2727272727272727,"size":"xl","textAlign":"start","w":952},"rotation":0,"type":"text","typeName":"shape","x":64,"y":56}}}$deck$;
  m record;
begin
  for m in select slug, id from metrics where workspace_id = 'd3e00000-0000-4000-8000-000000000001'
    and slug in ('revenue', 'cost', 'margin', 'orders', 'average-order-value', 'support-tickets', 'return-rate') loop
    doc := replace(doc, '"__M_' || m.slug || '__"', m.id::text);
  end loop;
  -- A Metric the demo no longer has would leave its placeholder: then the deck starts empty, as it did before.
  if doc like '%"\_\_M\_%' then
    insert into decks (owner_id, name) values ('sara', 'Board update, ' || to_char(current_date, 'FMMonth YYYY'));
    return;
  end if;
  doc := replace(doc, '__MONTH__', to_char(current_date, 'FMMonth YYYY'));
  insert into decks (owner_id, name, document) values ('sara', 'Board update, ' || to_char(current_date, 'FMMonth YYYY'), doc::jsonb);
end $function$;

revoke execute on function prototype_reset_decks() from public, anon, authenticated;
grant execute on function prototype_reset_decks() to service_role;
